INSERT INTO purpose VALUES('theory-cellular-sheaves','cochain::CochainComplex','struct','Holds a sheaf''s coboundaries over the rationals from an orientation, each two in turn composing to zero, so the coboundaries and the cohomology are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','cochain::Cohomology','struct','Holds the dimension of each degree of a sheaf''s cohomology over the rationals, so the dimension of a degree is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','error::SheafError','enum','Names why a sheaf construction refused an input: a cell, a map, a section, an orientation, a bonding map or a matched pair that does not fit, a walk past its budget, or arithmetic past the integers.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','index::CoverIndex','struct','Names a member of a cover by its place in the cover, so an obstruction''s two members are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','index::Dimension','struct','Names the dimension of a space of cochains or of a cohomology group, or the rank of a map between them, so the count is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','index::Entry','struct','Names an entry of a stalk, so an entry map''s target and an obstruction''s first difference are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','index::Incidence','enum','Names the sign with which a face enters the coboundary of a cell one rank above it, so an orientation is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','index::Integer','struct','Names a 128-bit integer, the numerator or the denominator of a rational, so a rational is built from its parts and its parts are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','index::Level','struct','Names a level of a tower from its coarsest, so a level''s cohomology and induced ranks are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','index::Slot','struct','Names a row or a column of a matrix, a position in a space of cochains, so a matrix entry''s place is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','index::Width','struct','Names the number of entries of a stalk or a section, so a stalk''s size is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','matrix::Matrix','struct','Holds a matrix over the rationals in exact lowest terms, so its shape, its rank, its kernel and its products are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','matrix::Rational','struct','Holds an exact rational in lowest terms with a positive denominator, so the entries of a matrix and the weights of a distribution are summed, multiplied and divided with no rounding.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','reduce::Oriented','struct','Holds a sheaf with an orientation as a complex over the integers, so the greedy matching pairs its cells and a reduction walks its gradient.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','reduce::Reduced','struct','Holds the cochains of a sheaf reduced along a compatible matching, so the critical cells and their cohomology, the sheaf''s own, are read.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::Agreement','enum','Names whether the sections of two cells agree where the cells overlap, or the least cell and the first entry where they differ.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::Chain','struct','Holds three cells, each strictly below the next, and the widths of their stalks, so a check that a sheaf''s maps compose reads one chain.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::Difference','enum','Names whether two maps or two restrictions agree, or the first entry where they differ, so a refusal of maps that do not compose names that entry.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::EntryMaps','struct','Names the kind of a sheaf whose maps are entry maps, so its sections hold values of any kind and each map reads one entry of the lower stalk.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::EntryTable','struct','Holds the entry maps of a sheaf in one list, each from its start, so the map of a pair of cells is read in its stalk''s width.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::Gluing','enum','Names the verdict on the sections of a cover: the glued section, or each pair of members whose restrictions differ.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::LinearMap','enum','Names the linear map of one pair of cells, an entry map or a matrix borrowed from its table, so a restriction, a term and a composite read it.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::LinearMaps','struct','Names the kind of a sheaf whose maps are homomorphisms of modules over the rationals, so a matrix states a map that no entry map states.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::LinearTable','struct','Holds the linear maps of a sheaf, each an entry map or a matrix, so the map of a pair of cells is read and an entry map stays the fast path.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::Maps','trait','Names a kind of map that a sheaf holds: its table, the map of a pair of cells, its terms and its first difference from a composite, so the constructor, the coboundaries and the check that maps compose read either kind.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::Obstruction','struct','Holds where two members of a cover differ: the pair, the least cell of their overlap and the first entry there.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::Restricted','enum','Names the value at one entry of a restriction: borrowed from the section, or summed by a row of a matrix, so an entry map copies no value.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::Restriction','enum','Names the map that a sheaf of linear maps takes for a pair of cells, an entry map or a matrix, so its constructor stores each in its own form.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::Restricts','trait','Names a kind of map through which a section of values restricts, so a gluing and a comparison read the value at each entry of an upper stalk.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::Section','struct','Holds a glued section on every cell above a member of a cover, so the values at a cell are read.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','sheaf::Sheaf','struct','Holds a cellular sheaf over a graded poset of at most 64 cells, its stalk widths and its composing maps, entry maps or linear maps, so a cover is glued and its cochains are read.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','tower::Image','enum','Names where a bonding map sends a cell of the finer level: onto a cell of its rank with a sign and a stalk map, or collapsed.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-cellular-sheaves','tower::Tower','struct','Holds the levels of a tower of sheaves with each level''s cohomology and the rank of each induced map, each bonding map checked to commute with the coboundaries.',NULL,'fits','sound',NULL);
